/**
 * Every internal link this app builds.
 *
 * The app is a static export, which can only serve paths that existed at build
 * time. Where the build can list every value – the genres, the streaming
 * platforms of the genre landings, the moods – each one is a path of its own
 * (`/genres/movie/action-28`, `/mood/easy-watch`), generated by
 * `generateStaticParams`, and that is what lets a search engine index them.
 * There is no build-time list of every film on TMDB, though, so a title travels
 * in the query string – `/movie` is a real page, `?id=fight-club-550` is what it
 * renders – except for the couple of thousand best-known titles and people the
 * build prerenders at a path of their own (see `titleHref`).
 *
 * Centralised because the choice is arbitrary. Changing how a title is addressed
 * should be one edit here rather than forty template literals, and building the
 * links through named functions is what makes the query strings composable –
 * a genre page carries its filters in the same place as its genre.
 */

import type { MediaType } from "@/types/tmdb";
import { extractIdFromSlug } from "./utils";
import {
  hasPrerenderedPage,
  type PrerenderedKind,
} from "./prerendered-titles";

function withParams(path: string, params: Record<string, string | undefined>) {
  const search = new URLSearchParams();

  for (const [key, value] of Object.entries(params)) {
    if (value) search.set(key, value);
  }

  const query = search.toString();
  return query ? `${path}?${query}` : path;
}

/**
 * A film, a series or a person: its own path when the build prerendered one,
 * the query-string page otherwise.
 *
 * The build prerenders the titles people search for by name
 * (`scripts/prebuild.mjs`), each at `createSlug(name, id)` – `fight-club-550`,
 * or a bare `12345` for a name with no Latin letters in it. So the path is used
 * only for a slug of one of those shapes that is also the very slug the build
 * wrote the page under (`hasPrerenderedPage` compares a hash of it). Any other
 * slug – a title TMDB renamed since it was saved, the old site's id-first
 * order, a bare id typed into the address bar – would name a file that does
 * not exist; it goes to the query page, which reads any form and canonicalises
 * to the path itself.
 */
function titleHref(kind: PrerenderedKind, slug: string): string {
  const id = extractIdFromSlug(slug);
  if (
    id !== null &&
    (slug === String(id) || slug.endsWith(`-${id}`)) &&
    hasPrerenderedPage(kind, id, slug)
  ) {
    return `/${kind}/${slug}`;
  }
  return titleQueryHref(kind, slug);
}

/**
 * Always the query-string page, which exists for every title. For the 404
 * page's redirects (`LegacyPathRedirect`): a path that just failed must never
 * be answered with a path again.
 */
export function titleQueryHref(kind: PrerenderedKind, slug: string): string {
  return withParams(`/${kind}`, { id: slug });
}

/** A film. `slug` is `createSlug(title, id)` – the id is the half that matters. */
export function movieHref(slug: string): string {
  return titleHref("movie", slug);
}

export function tvHref(slug: string): string {
  return titleHref("tv", slug);
}

export function mediaHref(mediaType: MediaType, slug: string): string {
  return mediaType === "movie" ? movieHref(slug) : tvHref(slug);
}

export function personHref(slug: string): string {
  return titleHref("person", slug);
}

export function collectionHref(slug: string): string {
  return withParams("/collection", { id: slug });
}

/** One day of the daily puzzle. No day means today, which is what `/daily` is. */
export function dailyHref(day?: string): string {
  return withParams("/daily", { day });
}

export function moodHref(slug: string, page?: number): string {
  return withParams(`/mood/${slug}`, {
    page: page && page > 1 ? String(page) : undefined,
  });
}

/**
 * A genre listing, optionally narrowed to one platform, optionally filtered.
 *
 * The genre and the platform are path segments – `/genres/movie/action-28` and
 * `/genres/movie/action-28/netflix` – because those are a fixed list the build
 * can enumerate, and a page with a path of its own is one a search engine can
 * index. Only the filters, which are endless, stay in the query string.
 *
 * `filterQuery` is what `buildDiscoverFilterQuery` returns – a leading "?" and
 * the filter params – so it is merged in rather than appended, or the second
 * question mark would swallow everything after it. A `genre` in it is the old
 * query-addressed form and is dropped: the path already says.
 *
 * A `provider` in it is the filter bar's own key – provider ids, "mine" or
 * "any" – and is kept, or paging through a genre filtered to one service would
 * lose the filter at page two. Only a landing drops it: its platform is the
 * path segment, and it has no filter bar to set one. (The old query-addressed
 * landing slug, `?provider=netflix`, is turned into a path by
 * `legacyGenreQueryTarget` before it gets here.)
 */
export function genreHref(
  mediaType: MediaType,
  genreSlug: string,
  options: { provider?: string; filterQuery?: string } = {},
): string {
  const params = new URLSearchParams(options.filterQuery ?? "");
  params.delete("genre");
  if (options.provider) params.delete("provider");

  const path = options.provider
    ? `/genres/${mediaType}/${genreSlug}/${options.provider}`
    : `/genres/${mediaType}/${genreSlug}`;
  const query = params.toString();
  return query ? `${path}?${query}` : path;
}

/** A shared list, with the optional name its sender gave it. */
export function sharedListHref(encoded: string, title?: string): string {
  return withParams("/list", { items: encoded, t: title });
}

/** Two shared lists, compared. */
export function matchHref(
  mine: string,
  theirs: string,
  options: { mineTruncated?: boolean } = {},
): string {
  return withParams("/match", {
    mine,
    theirs,
    mineTruncated: options.mineTruncated ? "1" : undefined,
  });
}

/**
 * The site's own origin, for the places a link has to be absolute: structured
 * data, the sitemap, the calendar export and shared text.
 *
 * Read from the environment so a preview deployment does not advertise the
 * production domain, with the production origin as the fallback an ordinary
 * build gets. Inlined at build time like every `NEXT_PUBLIC_` value, which is
 * what lets a Client Component read it.
 */
export const SITE_URL = (
  process.env.NEXT_PUBLIC_BASE_URL || "https://www.watch-list.me"
).replace(/\/+$/, "");

/**
 * One of the paths above, made absolute.
 *
 * Exists so absolute links are built from the same functions as internal ones.
 * Hand-written absolute URLs are how `/movie/fight-club-550` ended up in the
 * structured data and the `.ics` export: a path form that no route serves,
 * because every title here is addressed `/movie?id=…`.
 */
export function absoluteUrl(path: string): string {
  return `${SITE_URL}${path}`;
}

/** The canonical, absolute address of a title's page. */
export function absoluteMediaUrl(mediaType: MediaType, slug: string): string {
  return absoluteUrl(mediaHref(mediaType, slug));
}
